import React from 'react';

import { valueContent } from './MeterBarTooltipItem.sty.js';
import { TooltipPointIndicator } from '../../../../../core/components/tooltip/section-components/atoms/TooltipPointIndicator.js';
import { TooltipText } from '../../../../../core/components/tooltip/section-components/atoms/TooltipText.js';
import { TooltipInfoContent } from '../../../../../core/components/tooltip/section-components/TooltipInfoContent.js';
import { TooltipItem } from '../../../../../core/components/tooltip/section-components/TooltipItem.js';
import { TooltipSymbolContent } from '../../../../../core/components/tooltip/section-components/TooltipSymbolContent.js';
import { TooltipValueContent } from '../../../../../core/components/tooltip/section-components/TooltipValueContent.js';
import { TooltipItem as TooltipItemType } from '../../../../../core/types/tooltip.js';

interface MeterBarTooltipItemProps {
  item: TooltipItemType;
  activeItem?: boolean;
  showDivider?: boolean;
  actions?: () => React.ReactElement;
}

export const MeterBarTooltipItem = (props: MeterBarTooltipItemProps) => {
  const { item, actions, activeItem, showDivider } = props;

  return (
    <TooltipItem
      actions={actions}
      showDivider={showDivider}
      data-testid="chart-tooltip-item"
    >
      {item.color && (
        <TooltipSymbolContent>
          <TooltipPointIndicator
            color={item.color.Default}
            active={activeItem}
          />
        </TooltipSymbolContent>
      )}
      <TooltipInfoContent>
        <TooltipText>{item.name}</TooltipText>
      </TooltipInfoContent>
      {item.values && (
        <TooltipValueContent variant="chip" className={valueContent}>
          {item.values[0]}
        </TooltipValueContent>
      )}
    </TooltipItem>
  );
};

MeterBarTooltipItem['displayName'] = 'MeterBarTooltipItem';
